def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    fruit_patches = image_patch.find("fruit")
    serving_dish_patches = image_patch.find("serving dish")

    if not fruit_patches:
        return image_patch
    if not serving_dish_patches:
        return fruit_patches[0]

    # Assuming the serving dish is the one closest to the fruit in terms of depth
    closest_dish = None
    min_depth_diff = float('inf')

    for fruit in fruit_patches:
        for dish in serving_dish_patches:
            depth_diff = abs(fruit.compute_depth() - dish.compute_depth())
            if depth_diff < min_depth_diff:
                min_depth_diff = depth_diff
                closest_dish = dish

    return closest_dish if closest_dish else fruit_patches[0]

