def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    person_patches = image_patch.find("person")
    hand_patches = image_patch.find("hand")
    grill_patches = image_patch.find("grill")

    if not person_patches or not hand_patches or not grill_patches:
        return image_patch

    person_hand_pairs = []
    for person in person_patches:
        for hand in hand_patches:
            if abs(person.horizontal_center - hand.horizontal_center) < 20 and abs(person.vertical_center - hand.vertical_center) < 20:
                person_hand_pairs.append((person, hand))

    person_grill_pairs = []
    for person in person_patches:
        for grill in grill_patches:
            if abs(person.horizontal_center - grill.horizontal_center) < 50 and abs(person.vertical_center - grill.vertical_center) < 50:
                person_grill_pairs.append((person, grill))

    best_person = None
    best_score = -1
    for person, hand in person_hand_pairs:
        for _, grill in person_grill_pairs:
            score = abs(hand.horizontal_center - grill.horizontal_center) + abs(hand.vertical_center - grill.vertical_center)
            if score > best_score:
                best_score = score
                best_person = person

    return best_person

